        // If we have multiple removable characters, which one should we remove first?
        // Consider: if we remove a smaller character, it might prevent a larger character from being removed later?
        // Actually, removing a character only affects its neighbors. 
        // 
        // Let's think about it this way: 
        // A character can be removed if at least one of its neighbors is exactly one less.
        // If we have a sequence like "abc", we can remove 'c' (because 'b' is adjacent) -> "ab", then remove 'b' (because 'a' is adjacent) -> "a". Total 2 removals.
        // If we remove 'b' first: 'b' has 'a' and 'c' as neighbors. 'a' is one less than 'b', so we can remove 'b'. -> "ac". Now 'c' has 'a' as neighbor, but 'a' is not 'b', so 'c' cannot be removed. Total 1 removal.
        // So removing the larger character first is better.
        //
        // Therefore, the greedy strategy is: at each step, find the largest character that can be removed, and remove it.
        // If there are multiple, remove any of them (or the one that appears first? or last? let's just pick the largest value, and if tie, pick any).

        // Let's implement this greedy approach:
        // Repeat until no more removals are possible:
        //   Find the index i such that arr[i] is removable and arr[i] is as large as possible.
        //   If found, remove it and increment count.
        //   If not found, stop.

        boolean changed = true;
        while (changed) {
            changed = false;
            int bestIndex = -1;
            char bestChar = 0;

            for (int i = 0; i < arr.length; i++) {
                if (isRemovable(arr, i)) {
                    if (arr[i] > bestChar) {
                        bestChar = arr[i];
                        bestIndex = i;
                    }
                }
            }

            if (bestIndex != -1) {
                // Remove the character at bestIndex
                // Create a new array without the character at bestIndex
                char[] newArr = new char[arr.length - 1];
                int j = 0;
                for (int i = 0; i < arr.length; i++) {
                    if (i == bestIndex) continue;
                    newArr[j++] = arr[i];
                }
                arr = newArr;
                removed++;
                changed = true;
            }
        }

        System.out.println(removed);
    }

    static boolean isRemovable(char[] arr, int i) {
        if (arr[i] == 'a') return false; // 'a' has no previous letter

        char prev = (char)(arr[i] - 1);

        // Check left neighbor
        if (i > 0 && arr[i-1] == prev) return true;
        // Check right neighbor
        if (i < arr.length - 1 && arr[i+1] == prev) return true;

        return false;
    }
}
