        // Let's check example 2: bcda
        // b c d a
        // Removable: 
        // index 0: b, neighbor c. c is not prev of b (prev is a). Not removable.
        // index 1: c, neighbors b and d. b is prev of c. Removable.
        // index 2: d, neighbors c and a. c is prev of d. Removable.
        // index 3: a, no prev. Not removable.
        // Rightmost removable: index 2 (d). Remove it. String: b c a
        // Now: b c a
        // Removable: index 1 (c, neighbors b and a. b is prev). Removable.
        // index 0: b, neighbor c. Not removable.
        // Remove rightmost: index 1 (c). String: b a
        // Now: b a
        // Removable: index 0 (b, neighbor a). Removable.
        // Remove index 0: a
        // Total removed: 3. Correct!
        //
        // Example 3: abbbbb
        // a b b b b b
        // Removable:
        // index 0: a, no.
        // index 1: b, neighbors a and b. a is prev. Removable.
        // index 2: b, neighbors b and b. No a. Not removable.
        // ... all other b's have b neighbors, no a.
        // So only index 1 is removable.
        // Remove index 1: a b b b b
        // Now: a b b b b
        // Removable: index 1 (b, neighbor a). Removable.
        // Remove index 1: a b b b
        // Continue... each time remove the b next to a.
        // After 5 removals: a. Total 5. Correct!
        //
        // So the strategy: repeatedly find the rightmost removable character and remove it, until no more can be removed.

        char[] arr = s.toCharArray();
        int count = 0;
        boolean changed = true;
        while (changed) {
            changed = false;
            // Find the rightmost removable character
            int removeIndex = -1;
            for (int i = arr.length - 1; i >= 0; i--) {
                if (canRemove(arr, i)) {
                    removeIndex = i;
                    break;
                }
            }
            if (removeIndex != -1) {
                // Remove the character at removeIndex
                // Shift elements
                for (int i = removeIndex; i < arr.length - 1; i++) {
                    arr[i] = arr[i + 1];
                }
                arr[arr.length - 1] = 0; // Mark as empty, but we'll track length
                count++;
                changed = true;
            }
        }

        System.out.println(count);
    }

    static boolean canRemove(char[] arr, int i) {
        char c = arr[i];
        if (c == 'a') return false; // a has no previous letter

        char prev = (char)(c - 1);

        // Check left neighbor
        if (i > 0 && arr[i-1] == prev) {
            return true;
        }
        // Check right neighbor
        if (i < arr.length - 1 && arr[i+1] == prev) {
            return true;
        }

        return false;
    }
}
